import {QUEUE_STAGES} from './queue-core.js?v=2.17.3';

// Deterministic local guidance, not a language model. Never writes or advances status.
export const PROJECT_ADVISOR_VERSION=1;
const extensions=new Map(),has=(object,key)=>Object.prototype.hasOwnProperty.call(object||{},key);
const list=value=>Array.isArray(value)?JSON.parse(JSON.stringify(value)):[];
const positive=value=>value!==null&&value!==''&&Number.isFinite(Number(value))&&Number(value)>0;
const stamp=value=>{const result=Date.parse(value||'');return Number.isFinite(result)?result:null};
const dateOnly=value=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(String(value||'')))return null;const date=new Date(value+'T12:00:00Z');return Number.isFinite(date.getTime())&&date.toISOString().slice(0,10)===value?value:null};
