const priorities={PROJECT_SCOPE_MISMATCH:100,DELIVERY_OVERDUE:99,STATUS_MISMATCH:95,PAYMENT_PENDING:90,QUOTE_MISSING:89,DELIVERY_QUOTE_MISMATCH:88,DELIVERY_MISSING:85,DELIVERY_SOON:84,RETURN_DUE:83,ART_FILE_MISSING:80,ART_DIMENSIONS_MISSING:79,PRINT_READINESS_PENDING:78,ARTWORK_MISSING:77};
const evidence=(source,row,field)=>({source,id:row?.id||row?.asset_id||null,field,value:row?.[field]??null});
const latest=(a,b)=>(Number(b.sequence_no)||0)-(Number(a.sequence_no)||0)||(stamp(b.started_at||b.created_at)||0)-(stamp(a.started_at||a.created_at)||0)||String(b.id||'').localeCompare(String(a.id||''));
const documentOrder=(a,b)=>(Number(b.document_version)||0)-(Number(a.document_version)||0)||(stamp(b.generated_at)||0)-(stamp(a.generated_at)||0);
const html=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));

/** Register a reviewed, synchronous rule alongside future application features. */
export function registerProjectAdvisorRule(rule){
  if(!rule||!/^[-a-z0-9_]{1,80}$/i.test(rule.id)||typeof rule.run!=='function'||!Array.isArray(rule.requires||[]))throw new Error('Regra do orientador inválida.');
  if(extensions.has(rule.id))throw new Error('Já existe uma regra com este identificador.');extensions.set(rule.id,{...rule,requires:[...(rule.requires||[])]});return ()=>extensions.delete(rule.id);
}
export function evaluateProjectAdvice(input={}){
  const incomplete=new Set(),known={},workspace=input.workspace?JSON.parse(JSON.stringify(input.workspace)):null;
  const names=['projects','statuses','quotes','quoteItems','assets','printProfiles','folders','documents','teamProfiles'];
  const data={};for(const name of names){known[name]=input.known?.[name]!==false&&Array.isArray(input[name]);data[name]=list(input[name]);}
  const result={version:1,workspaceId:workspace?.id||null,projectId:null,stage:null,closed:false,applicable:true,issues:[],summary:'Dados insuficientes para orientar este projeto.',nextAction:null,incomplete:[],confidence:'partial',counts:{quotes:0,paidQuotes:0,arts:0,readyArts:0},queuePosition:null};
  if(!workspace?.id){result.incomplete=['workspace'];return result}
