  else if(known.teamProfiles){const member=data.teamProfiles.find(row=>row.id===responsible&&(!row.account_owner_id||!workspace.owner_id||row.account_owner_id===workspace.owner_id));if(!member||member.active===false)add('RESPONSIBLE_UNAVAILABLE','warning','Confira o responsável','O responsável não aparece na equipe ativa carregada. Confirme quem seguirá com o pedido.',[evidence('workspace',workspace,'responsible_user_id'),...(member?[evidence('profile',member,'active')]:[])],action('edit_workspace','Revisar responsável'))}

  let today=dateOnly(input.today);const now=input.now instanceof Date?input.now:new Date(input.now??Date.now());
  if(!today&&Number.isFinite(now.getTime())){try{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:input.timeZone||'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now),part=type=>parts.find(p=>p.type===type).value;today=`${part('year')}-${part('month')}-${part('day')}`}catch{incomplete.add('currentDate')}}
  const delivery=dateOnly(project.delivery_date);
  if(!has(project,'delivery_date'))incomplete.add('project.delivery_date');
  else if(project.delivery_date&&!delivery)add('DELIVERY_INVALID','warning','Data de entrega inválida','A data registrada não é um dia válido. Confira o calendário do pedido.',[evidence('project',project,'delivery_date')],action('set_delivery','Corrigir entrega'));
  else if(!delivery&&(operational||paid.length))add('DELIVERY_MISSING',operational?'critical':'warning','Defina a data de entrega','A fila operacional exige a data do projeto, além de um orçamento pago.',[evidence('project',project,'delivery_date')],action('set_delivery','Escolher entrega'));
  const differentQuoteDates=delivery?paid.filter(quote=>dateOnly(quote.delivery_date)&&quote.delivery_date!==delivery):[];
  if(known.quotes&&differentQuoteDates.length)add('DELIVERY_QUOTE_MISMATCH','warning','Projeto e orçamento com prazos diferentes','A data usada na fila difere da registrada em orçamento pago. Confira o prazo combinado antes de enviar o PDF ao cliente. Gerar um PDF não altera automaticamente essas datas nem o pagamento.',[evidence('project',project,'delivery_date'),...differentQuoteDates.map(quote=>evidence('quote',quote,'delivery_date'))],action('open_quote_pdf','Revisar orçamento e prazo',{quoteId:differentQuoteDates[0].id}));
  if(delivery&&today){const delta=Math.round((Date.parse(delivery+'T12:00:00Z')-Date.parse(today+'T12:00:00Z'))/86400000);if(delta<0)add('DELIVERY_OVERDUE','critical',`Entrega vencida há ${-delta} dia(s)`,'O projeto ainda está aberto e a data combinada já passou. Confira a produção e combine o próximo passo com o cliente.',[evidence('project',project,'delivery_date')],action('open_workspace','Revisar pedido atrasado'));else if(delta<=1)add('DELIVERY_SOON','warning',delta===0?'Entrega prevista para hoje':'Entrega prevista para amanhã','Confira as artes, a fila e o andamento antes do prazo.',[evidence('project',project,'delivery_date')],action('open_workspace','Conferir entrega'))}
  const reminder=stamp(project.reminder_at);if(reminder!==null&&Number.isFinite(now.getTime())&&reminder<=now.getTime())add('RETURN_DUE','warning','Retorno programado chegou','Este projeto possui um retorno agendado já vencido. Confira se o atendimento foi realizado.',[evidence('project',project,'reminder_at')],action('open_workspace','Retomar atendimento'));

  const paymentKnown=known.quotes&&quotes.every(quote=>['paid','unpaid','pending'].includes(quote.payment_status));
  if(known.quotes){if(!quotes.length)add('QUOTE_MISSING',operational?'critical':'warning','Monte o orçamento deste projeto','Nenhum orçamento foi encontrado vinculado ao projeto atual. Orçamentos de projetos anteriores não liberam esta produção.',[evidence('project',project,'id')],action('new_quote','Criar orçamento'));
    else if(!paymentKnown)incomplete.add('quotes.payment_status');
    else if(!paid.length)add('PAYMENT_PENDING',operational?'critical':'warning',operational?'Produção sem pagamento confirmado':'Pagamento ainda não confirmado','Nenhum orçamento do projeto está marcado como pago. Confira o recebimento; esta orientação não marca pagamentos automaticamente.',quotes.map(quote=>evidence('quote',quote,'payment_status')),action('review_payment','Conferir pagamento',{quoteId:quotes[0].id}));
    else if(quotes.some(quote=>quote.payment_status!=='paid'))add('ADDITIONAL_QUOTE_PENDING','info','Há outro orçamento pendente','Existe orçamento pago que atende à regra da fila, mas também há orçamento pendente no mesmo projeto. Confirme quais itens fazem parte desta produção.',quotes.filter(quote=>quote.payment_status!=='paid').map(quote=>evidence('quote',quote,'payment_status')),action('review_payment','Conferir os orçamentos'));
    const legacy=data.quotes.filter(quote=>quote.workspace_id===workspace.id&&!quote.project_id&&own(quote));if(!quotes.length&&legacy.length)add('UNLINKED_QUOTES','warning','Orçamento sem projeto vinculado','Há orçamento da empresa sem vínculo de projeto. Confira o histórico e o vínculo; não o considere automaticamente como pagamento deste pedido.',legacy.map(quote=>evidence('quote',quote,'project_id')),action('open_workspace','Conferir vínculo do orçamento'));
  }
  if(known.quoteItems){for(const quote of quotes){const rows=data.quoteItems.filter(row=>row.quote_id===quote.id&&own(row));if(!rows.length)add('QUOTE_EMPTY','warning','Orçamento sem produtos','Há um orçamento do projeto sem itens cadastrados. Revise antes de enviar ao cliente.',[evidence('quote',quote,'id')],action('new_quote','Revisar orçamento',{quoteId:quote.id}));else if(rows.some(row=>!positive(row.quantity)))add('QUOTE_QUANTITY_INVALID','warning','Quantidade inválida no orçamento','Um item tem quantidade nula, zero ou inválida. Revise o orçamento antes de produzir.',rows.filter(row=>!positive(row.quantity)).map(row=>evidence('quote_item',row,'quantity')),action('open_workspace','Revisar quantidades',{quoteId:quote.id}))}}
  if(known.documents&&known.quotes){for(const quote of quotes){const doc=documents.filter(row=>row.quote_id===quote.id).sort(documentOrder)[0];if(!doc)add('QUOTE_PDF_MISSING','info','Gere o PDF atualizado','O orçamento já existe, mas ainda não tem PDF registrado para compartilhar.',[evidence('quote',quote,'id')],action('open_quote_pdf','Gerar PDF',{quoteId:quote.id}));else if(doc.stale===true||stamp(quote.updated_at)!==null&&stamp(doc.quote_updated_at)!==null&&stamp(quote.updated_at)>stamp(doc.quote_updated_at))add('QUOTE_PDF_STALE','warning','O PDF está desatualizado','O orçamento mudou depois da versão registrada. Gere o PDF novamente antes de compartilhar.',[evidence('document',doc,'stale'),evidence('document',doc,'quote_updated_at'),evidence('quote',quote,'updated_at')],action('open_quote_pdf','Atualizar PDF',{quoteId:quote.id}))}}

  const inReadyFolder=asset=>{const seen=new Set();let id=asset.folder_id;while(id&&!seen.has(id)){seen.add(id);const folder=folders.find(row=>row.id===id);if(!folder)return false;if(folder.purpose==='artes_prontas')return true;id=folder.parent_id}return false};
  const dimensions=profile=>positive(profile?.default_width_cm)&&positive(profile?.default_height_cm),ready=arts.filter(asset=>profiles.get(asset.id)?.ready_for_print===true&&dimensions(profiles.get(asset.id))&&(asset.processed_path||asset.original_path));
  if(known.assets&&assets.some(asset=>!has(asset,'asset_type')))incomplete.add('assets.asset_type');
  else if(known.assets&&!arts.length&&(operational||paid.length))add('ARTWORK_MISSING',stage==='ready_production'||stage==='production'?'critical':'warning','Adicione as artes deste projeto','O pedido tem atividade de produção, mas não há artes vinculadas ao projeto atual.',[evidence('project',project,'id')],action('upload_art','Adicionar arte'));
  if(known.assets&&known.printProfiles){
    const intended=arts.filter(asset=>profiles.get(asset.id)?.ready_for_print===true||asset.metadata?.print_ready_intent===true||known.folders&&inReadyFolder(asset));
    const dimensionsKnown=asset=>!profiles.has(asset.id)||has(profiles.get(asset.id),'default_width_cm')&&has(profiles.get(asset.id),'default_height_cm');
    const fileKnown=asset=>Boolean(asset.processed_path||asset.original_path)||has(asset,'processed_path')&&has(asset,'original_path');
    if(intended.some(asset=>!dimensionsKnown(asset)))incomplete.add('printProfiles.dimensions');
    if(intended.some(asset=>!fileKnown(asset)))incomplete.add('assets.file_path');
    const withoutSize=intended.filter(asset=>dimensionsKnown(asset)&&!dimensions(profiles.get(asset.id)));
    if(withoutSize.length)add('ART_DIMENSIONS_MISSING','critical',`${withoutSize.length} arte(s) pronta(s) sem medida válida`,'Para entrar no filme, a arte precisa de largura e altura positivas em centímetros. Confira cada tamanho no cadastro.',withoutSize.map(asset=>({source:'asset',id:asset.id,field:'print_dimensions',value:{widthCm:profiles.get(asset.id)?.default_width_cm??null,heightCm:profiles.get(asset.id)?.default_height_cm??null}})),action('edit_print_profile','Definir medida',{assetId:withoutSize[0].id}));
    const missingFile=intended.filter(asset=>has(asset,'processed_path')&&has(asset,'original_path')&&!asset.processed_path&&!asset.original_path);if(missingFile.length)add('ART_FILE_MISSING','critical','Arte liberada sem arquivo','Há arte marcada para impressão sem caminho de arquivo disponível. Confira o cadastro antes de montar o filme.',missingFile.map(asset=>evidence('asset',asset,'id')),action('edit_print_profile','Revisar arte',{assetId:missingFile[0].id}));
    const halftones=arts.filter(asset=>{const p=profiles.get(asset.id);return p?.ready_for_print&&p.halftone===true&&p.allow_internal_nesting===true});if(halftones.length)add('HALFTONE_NESTING_REVIEW','warning','Revise o encaixe de arte halftone','Há perfil halftone com encaixe interno ligado. O cálculo deve preservar a área retangular, sem encaixar outra arte nos pontos transparentes.',halftones.map(asset=>evidence('print_profile',profiles.get(asset.id),'allow_internal_nesting')),action('edit_print_profile','Revisar halftone',{assetId:halftones[0].id}));
    const mismatch=arts.filter(asset=>{const p=profiles.get(asset.id);return p?.ready_for_print&&dimensions(p)&&positive(p.aspect_ratio)&&Math.abs(Number(p.default_width_cm)/Number(p.default_height_cm)/Number(p.aspect_ratio)-1)>.01});if(mismatch.length)add('ART_PROPORTION_MISMATCH','warning','Medidas e proporção divergentes','A proporção cadastrada difere da relação entre largura e altura em mais de 1%. Confira para não esticar a arte.',mismatch.map(asset=>evidence('print_profile',profiles.get(asset.id),'aspect_ratio')),action('edit_print_profile','Conferir proporção',{assetId:mismatch[0].id}));
    const readinessKnown=arts.every(asset=>!profiles.has(asset.id)||has(profiles.get(asset.id),'ready_for_print')&&dimensionsKnown(asset)&&fileKnown(asset));
    if(!readinessKnown)incomplete.add('printProfiles.readiness');
    if(readinessKnown&&arts.length&&!ready.length&&!withoutSize.length&&['ready_production','production'].includes(stage))add('PRINT_READINESS_PENDING','critical','Nenhuma arte liberada para o filme','Há artes no projeto, mas nenhuma combina liberação, medidas válidas e arquivo. Revise os perfis antes de imprimir.',arts.map(asset=>evidence('asset',asset,'id')),action('edit_print_profile','Revisar liberação',{assetId:arts[0].id}));
  }
  result.counts={quotes:quotes.length,paidQuotes:paid.length,arts:arts.length,readyArts:ready.length};
  if(input.queueSnapshot){if(input.queueSnapshot.error)incomplete.add('queueSnapshot');else{const row=(input.queueSnapshot.rows||[]).find(row=>row.project?.id===project.id&&row.workspace?.id===workspace.id);if(row){result.queuePosition=row.position??null;if(row.stage!==stage)add('QUEUE_STAGE_MISMATCH','warning','Atualize a leitura da fila','O projeto e o retrato carregado da fila mostram etapas diferentes. Atualize a consulta antes de decidir.',[{source:'queue',id:project.id,field:'stage',value:row.stage},evidence('status',status,'queue_stage')],action('open_queue','Reabrir fila',{stage:QUEUE_STAGES.includes(stage)?stage:row.stage}))}}}
  const context={workspace,project,status,stage,closed:result.closed,quotes,assets:arts,printProfiles,folders,documents,quoteItems:data.quoteItems.filter(row=>quoteIds.has(row.quote_id)&&own(row)),teamProfiles:data.teamProfiles.filter(own),known:{...known},today,counts:{...result.counts},action};
  for(const rule of extensions.values()){if(rule.requires.some(name=>!known[name])){incomplete.add('rule:'+rule.id);continue}try{const items=rule.run(context)||[];if(!Array.isArray(items))throw new Error('A regra precisa ser síncrona e retornar uma lista.');for(const issue of items){if(!issue||typeof issue.code!=='string'||!rank.hasOwnProperty(issue.severity)||!Array.isArray(issue.evidence)||!issue.evidence.length)throw new Error('Regra sem evidência válida.');add(issue.code,issue.severity,String(issue.title||''),String(issue.detail||''),issue.evidence,issue.recommendedAction||action('open_workspace','Revisar pedido'))}}catch{incomplete.add('rule:'+rule.id)}}
