  function finish(){
    result.issues.sort((a,b)=>rank[a.severity]-rank[b.severity]||b.priority-a.priority||a.code.localeCompare(b.code));result.incomplete=[...incomplete];result.confidence=incomplete.size?'partial':'complete';
