    else if(!result.closed&&!result.nextAction)result.summary=incomplete.size?'Leitura parcial: abra o projeto para conferir os dados disponíveis.':'Nenhuma pendência detectada nos dados conferidos.';
    if(!result.nextAction)result.nextAction=action('open_workspace','Abrir projeto');return result;
  }
}

/** Optional markup only. The caller handles data-advisor-code using the returned action. */
export function renderProjectAdvice(advice,{compact=false}={}){
  if(!advice?.applicable)return '';
  const top=advice.issues[0],severity=top?.severity||'info',tag=advice.confidence==='partial'?'Leitura parcial':'Dados conferidos';
  if(compact)return `<div class="project-advice-badge ${html(severity)}"><span>${html(advice.summary)}</span><small>${html(tag)}</small></div>`;
  return `<section class="project-advisor" aria-label="Orientador do projeto"><header><div><span class="eyebrow">Próximo passo · orientador local</span><h2>${html(advice.summary)}</h2></div><span class="project-advice-confidence">${html(tag)}</span></header><p>Regras baseadas nos registros deste projeto. Nada é enviado a uma IA e nenhuma etapa é alterada automaticamente.</p>${advice.issues.length?`<div class="project-advice-list">${advice.issues.map(issue=>`<article class="${html(issue.severity)}"><b>${html(issue.title)}</b><p>${html(issue.detail)}</p><details><summary>Por que este aviso apareceu?</summary><ul>${issue.evidence.map(fact=>`<li>${html(fact.source)} · ${html(fact.field)}: ${html(typeof fact.value==='object'?JSON.stringify(fact.value):fact.value??'não informado')}</li>`).join('')}</ul></details><button class="btn small" type="button" data-advisor-code="${html(issue.code)}">${html(issue.recommendedAction?.label||'Revisar')}</button></article>`).join('')}</div>`:`<button class="btn primary" data-advisor-code="next">${html(advice.nextAction?.label||'Abrir projeto')}</button>`}${advice.incomplete.length?'<small class="project-advice-incomplete">Algumas verificações dependem de dados ainda não carregados. Ausência de aviso não confirma que tudo está pronto.</small>':''}</section>`;
}

project-history.css:
.project-history-row-interactive{grid-template-columns:minmax(0,1fr) auto auto auto;padding:13px;gap:12px}
.project-history-row-interactive b{font-size:13px;white-space:normal;overflow-wrap:anywhere}
.project-history-row-interactive small{font-size:11px;white-space:normal;overflow-wrap:anywhere}
.project-history-current{width:max-content;margin-top:5px;color:#ffac85;font-size:10px;font-weight:800}
.project-history-backdrop,.project-history-preview-backdrop{z-index:90;align-items:center;padding:18px}
.project-history-preview-backdrop{z-index:91}
.project-history-modal,.project-history-asset-preview{width:min(1080px,100%);max-height:92vh;max-height:92dvh;overscroll-behavior:contain}
.project-history-modal .modal-head>div,.project-history-asset-preview .modal-head>div{min-width:0}
.project-history-modal h2,.project-history-asset-preview h2{overflow-wrap:anywhere}
.project-history-modal .modal-head>button,.project-history-asset-preview .modal-head>button{flex-shrink:0}
.history-readonly-note{display:flex;flex-wrap:wrap;gap:8px 16px;align-items:center;background:rgba(255,100,40,.1);border:1px solid rgba(255,100,40,.22);border-radius:12px;padding:13px;margin-bottom:16px}
.history-readonly-note b{color:#ffad88;font-size:13px}.history-readonly-note span{font-size:12px;color:#b7b7bf}
.history-project-facts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}
.history-project-facts>div{display:grid;gap:5px;padding:12px;background:#1a1a1f;border-radius:11px;min-width:0;overflow-wrap:anywhere}
.history-project-facts small{font-size:11px;color:#a2a2ad}.history-project-facts b{font-size:13px}
.history-quotes-section,.history-files-section{margin-top:26px}.history-quotes-section h3,.history-files-section h3{font-size:17px;margin:0 0 12px}
.history-quote{border:1px solid #303038;border-radius:13px;overflow:hidden;margin-top:9px;background:#17171c}
.history-quote>summary{cursor:pointer;display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding:14px;list-style:none}
.history-quote>summary:before{content:'+';font-size:22px;color:#ff9c6d}.history-quote[open]>summary:before{content:'−'}
.history-quote>summary>span:first-of-type{display:grid;gap:5px;min-width:0;flex:1 1 160px;overflow-wrap:anywhere}
